### 4.3 Fullscreen Player & Media Keys Integration (`#view-player`)

When the application is in `#view-player`, remote media keys must control the HTML5 `<video>` pipeline and OSD overlay:

```javascript
CinejoyApp.handleMediaKey = function (action) {
  var video = document.getElementById('main-video-player');
  if (!video) return;

  var playBtn = document.getElementById('osd-play-btn');
  var fwdBtn = document.getElementById('osd-forward-btn');
  var rwdBtn = document.getElementById('osd-rewind-btn');

  switch (action) {
    case 'MEDIA_PLAY':
      video.play();
      break;

    case 'MEDIA_PAUSE':
      video.pause();
      break;

    case 'MEDIA_PLAY_PAUSE':
      if (video.paused) {
        video.play();
      } else {
        video.pause();
      }
      break;

    case 'MEDIA_STOP':
      video.pause();
      this.exitPlayer();
      break;

    case 'MEDIA_FAST_FORWARD':
      video.currentTime = Math.min(video.duration || Infinity, video.currentTime + 10);
      break;

    case 'MEDIA_REWIND':
      video.currentTime = Math.max(0, video.currentTime - 10);
      break;
  }
};
```

